use azalea_client::{test_utils::prelude::*,inventory::{ContainerClickEvent,PlayerInventoryState,shared_slots::ExtraPlayerEquipment},packet::game::SendGamePacketEvent};
use azalea_entity::inventory::Inventory;
use azalea_inventory::{ItemStack,operations::{ClickOperation,PickupClick,QuickMoveClick}};
use azalea_protocol::packets::{ConnectionProtocol,game::*};
use azalea_registry::builtin::{ItemKind,MenuKind};use bevy_ecs::prelude::*;use std::sync::{Arc,Mutex};
fn item(kind:ItemKind,count:i32)->ItemStack{ItemStack::new(kind,count)}
fn fresh()->Simulation{let mut sim=Simulation::new(ConnectionProtocol::Game);sim.receive_packet(default_login_packet());sim.update();sim}
fn content(sim:&mut Simulation,id:i32,state:u32,slots:Vec<ItemStack>,carried:ItemStack){sim.receive_packet(ClientboundContainerSetContent{container_id:id,state_id:state,items:slots,carried_item:carried});sim.update();}
fn open(sim:&mut Simulation){sim.receive_packet(ClientboundOpenScreen{container_id:5,menu_type:MenuKind::Generic9x3,title:azalea_chat::FormattedText::from("Alias fixture")});sim.update();}
fn slot(sim:&mut Simulation,id:i32,state:u32,index:u16,stack:ItemStack){sim.receive_packet(ClientboundContainerSetSlot{container_id:id,state_id:state,slot:index,item_stack:stack});sim.update();}
fn aliases(inv:&Inventory){if let Some(menu)=&inv.container_menu{let player=inv.inventory_menu.slots();let active=menu.slots();assert_eq!(&player[inv.inventory_menu.player_slots_range()],&active[menu.player_slots_range()]);}}
#[test]fn actual_player_and_container_slot_packets_and_pickup_share_inventory(){
 let mut sim=fresh();let mut player=vec![ItemStack::Empty;46];player[9]=item(ItemKind::Stone,8);player[36]=item(ItemKind::Arrow,3);player[5]=item(ItemKind::IronHelmet,1);player[45]=item(ItemKind::Shield,1);content(&mut sim,0,7,player,ItemStack::Empty);open(&mut sim);
 let inv=sim.component::<Inventory>();aliases(&inv);assert_eq!(inv.menu().slot(27),Some(&item(ItemKind::Stone,8)));assert_eq!(inv.menu().slot(54),Some(&item(ItemKind::Arrow,3)));
 let mut chest=vec![ItemStack::Empty;63];chest[0]=item(ItemKind::GoldIngot,4);chest[27]=item(ItemKind::Stone,8);chest[54]=item(ItemKind::Arrow,3);content(&mut sim,5,9,chest,ItemStack::Empty);
 slot(&mut sim,0,10,9,item(ItemKind::Dirt,4));slot(&mut sim,0,11,36,item(ItemKind::Apple,3));let inv=sim.component::<Inventory>();aliases(&inv);assert_eq!(inv.state_id,9);assert_eq!(sim.component::<PlayerInventoryState>().state_id,11);assert_eq!(inv.menu().slot(27),Some(&item(ItemKind::Dirt,4)));assert_eq!(inv.menu().slot(54),Some(&item(ItemKind::Apple,3)));
 slot(&mut sim,5,12,28,item(ItemKind::Coal,7));slot(&mut sim,5,13,0,item(ItemKind::GoldIngot,5));let inv=sim.component::<Inventory>();aliases(&inv);assert_eq!(inv.inventory_menu.slot(10),Some(&item(ItemKind::Coal,7)));assert_eq!(inv.inventory_menu.slot(5),Some(&item(ItemKind::IronHelmet,1)));assert_eq!(inv.inventory_menu.slot(45),Some(&item(ItemKind::Shield,1)));
 let packets=Arc::new(Mutex::new(Vec::new()));let out=packets.clone();sim.app.world_mut().add_observer(move|event:On<SendGamePacketEvent>|{if let ServerboundGamePacket::ContainerClick(p)=&event.packet{out.lock().unwrap().push(p.clone());}});sim.app.world_mut().trigger(ContainerClickEvent{entity:sim.entity,window_id:5,operation:ClickOperation::Pickup(PickupClick::Left{slot:Some(28)})});sim.app.world_mut().flush();sim.update();let inv=sim.component::<Inventory>();aliases(&inv);assert!(inv.inventory_menu.slot(10).unwrap().is_empty());assert_eq!(inv.carried,item(ItemKind::Coal,7));let packets=packets.lock().unwrap();assert_eq!(packets.len(),1);assert_eq!(packets[0].state_id,13);assert!(packets[0].changed_slots[&28].0.is_none());assert_eq!(packets[0].carried_item.0.as_ref().unwrap().count,7);
 slot(&mut sim,6,99,27,item(ItemKind::Diamond,64));slot(&mut sim,5,99,999,item(ItemKind::Diamond,64));slot(&mut sim,0,99,999,item(ItemKind::Diamond,64));let inv=sim.component::<Inventory>();aliases(&inv);assert_eq!(inv.state_id,13);assert_eq!(sim.component::<PlayerInventoryState>().state_id,11);
}
#[test]fn actual_inactive_player_full_contents_survive_container_close(){
 let mut sim=fresh();content(&mut sim,0,7,vec![ItemStack::Empty;46],ItemStack::Empty);open(&mut sim);let mut chest=vec![ItemStack::Empty;63];chest[0]=item(ItemKind::GoldIngot,5);content(&mut sim,5,13,chest,item(ItemKind::Coal,7));
 let mut player=vec![ItemStack::Empty;46];player[9]=item(ItemKind::Diamond,1);player[36]=item(ItemKind::Carrot,4);content(&mut sim,0,17,player,item(ItemKind::IronIngot,2));let inv=sim.component::<Inventory>();aliases(&inv);assert_eq!(inv.state_id,13);assert_eq!(inv.carried,item(ItemKind::Coal,7));assert_eq!(inv.menu().slot(0),Some(&item(ItemKind::GoldIngot,5)));
 sim.receive_packet(ClientboundContainerClose{container_id:5});sim.update();let inv=sim.component::<Inventory>();assert_eq!(inv.state_id,17);assert_eq!(inv.carried,item(ItemKind::IronIngot,2));assert_eq!(inv.inventory_menu.slot(9),Some(&item(ItemKind::Diamond,1)));assert_eq!(inv.inventory_menu.slot(36),Some(&item(ItemKind::Carrot,4)));
}
#[test]fn actual_raw_player_inventory_indices_equipment_cursor_and_login_lifecycle(){
 let mut sim=fresh();content(&mut sim,0,7,vec![ItemStack::Empty;46],ItemStack::Empty);open(&mut sim);content(&mut sim,5,13,vec![ItemStack::Empty;63],ItemStack::Empty);
 for(raw,mapped)in[(0,36),(8,44),(9,9),(35,35),(36,8),(37,7),(38,6),(39,5),(40,45)]{let stack=item(ItemKind::Stone,raw as i32+1);sim.receive_packet(ClientboundSetPlayerInventory{slot:raw,contents:stack.clone()});sim.update();let inv=sim.component::<Inventory>();aliases(&inv);assert_eq!(inv.inventory_menu.slot(mapped),Some(&stack));assert_eq!(inv.state_id,13);assert_eq!(sim.component::<PlayerInventoryState>().state_id,7);}
 for(raw,kind)in[(41,ItemKind::DiamondChestplate),(42,ItemKind::Saddle)]{sim.receive_packet(ClientboundSetPlayerInventory{slot:raw,contents:item(kind,1)});sim.update();}let extra=sim.component::<ExtraPlayerEquipment>();assert_eq!(extra.body,item(ItemKind::DiamondChestplate,1));assert_eq!(extra.saddle,item(ItemKind::Saddle,1));
 let before=sim.component::<Inventory>().inventory_menu.slots();for raw in[43,u32::MAX]{sim.receive_packet(ClientboundSetPlayerInventory{slot:raw,contents:item(ItemKind::Diamond,64)});sim.update();}assert_eq!(sim.component::<Inventory>().inventory_menu.slots(),before);
 sim.receive_packet(ClientboundSetCursorItem{contents:item(ItemKind::Emerald,2)});sim.update();assert_eq!(sim.component::<Inventory>().carried,item(ItemKind::Emerald,2));assert_eq!(sim.component::<Inventory>().state_id,13);
 sim.receive_packet(default_login_packet());sim.update();assert!(sim.app.world().get::<ExtraPlayerEquipment>(sim.entity).is_none());assert!(sim.app.world().get::<PlayerInventoryState>(sim.entity).is_none());
}
#[test]fn actual_container_quick_move_prediction_mirrors_player_without_consuming_carried(){
 let mut sim=fresh();open(&mut sim);let mut chest=vec![ItemStack::Empty;63];chest[0]=item(ItemKind::GoldIngot,5);content(&mut sim,5,13,chest,ItemStack::Empty);sim.app.world_mut().trigger(ContainerClickEvent{entity:sim.entity,window_id:5,operation:ClickOperation::QuickMove(QuickMoveClick::Left{slot:0})});sim.app.world_mut().flush();sim.update();let inv=sim.component::<Inventory>();aliases(&inv);assert!(inv.menu().slot(0).unwrap().is_empty());assert!(inv.carried.is_empty());assert_eq!(inv.inventory_menu.slots().iter().filter_map(|stack|if let ItemStack::Present(i)=stack{(i.kind==ItemKind::GoldIngot).then_some(i.count)}else{None}).sum::<i32>(),5);
}
